2. **Create `Dockerfile` in project root:**
   ```dockerfile
   # Stage 1: Build stage
   FROM node:22-alpine AS builder

   WORKDIR /app

   # Copy package files
   COPY package.json package-lock.json ./

   # Install dependencies (use --legacy-peer-deps as per vercel.json)
   RUN npm ci --legacy-peer-deps

   # Copy source code
   COPY . .

   # Build the application
   RUN npm run build

   # Stage 2: Production serve stage
   FROM nginx:alpine

   # Copy custom nginx configuration
   COPY nginx.conf /etc/nginx/nginx.conf

   # Copy built assets from builder stage
   COPY --from=builder /app/dist /usr/share/nginx/html

   # Expose port 80
   EXPOSE 80

   # Health check
   HEALTHCHECK --interval=30s --timeout=3s --start-period=5s --retries=3 \
     CMD wget --no-verbose --tries=1 --spider http://localhost/ || exit 1

   # Start nginx
   CMD ["nginx", "-g", "daemon off;"]
   ```

3. **Create `nginx.conf` in project root:**
   ```nginx
   user nginx;
   worker_processes auto;
   error_log /var/log/nginx/error.log warn;
   pid /var/run/nginx.pid;

   events {
       worker_connections 1024;
   }

   http {
       include /etc/nginx/mime.types;
       default_type application/octet-stream;

       log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                       '$status $body_bytes_sent "$http_referer" '
                       '"$http_user_agent" "$http_x_forwarded_for"';

       access_log /var/log/nginx/access.log main;

       sendfile on;
       tcp_nopush on;
       tcp_nodelay on;
       keepalive_timeout 65;
       types_hash_max_size 2048;

       # Gzip compression
       gzip on;
       gzip_vary on;
       gzip_proxied any;
       gzip_comp_level 6;
       gzip_types text/plain text/css text/xml text/javascript 
                  application/json application/javascript application/xml+rss 
                  application/rss+xml font/truetype font/opentype 
                  application/vnd.ms-fontobject image/svg+xml;
       gzip_disable "msie6";

       server {
           listen 80;
           server_name _;
           root /usr/share/nginx/html;
           index index.html;

           # Security headers (matching vercel.json)
           add_header X-Content-Type-Options "nosniff" always;
           add_header X-Frame-Options "DENY" always;
           add_header Referrer-Policy "strict-origin-when-cross-origin" always;
           add_header Permissions-Policy "camera=(), microphone=(), geolocation=()" always;
           add_header Strict-Transport-Security "max-age=63072000; includeSubDomains; preload" always;
           add_header Content-Security-Policy "default-src 'self'; script-src 'self' https://challenges.cloudflare.com; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' blob: data: https://*.supabase.co; connect-src 'self' https://*.supabase.co wss://*.supabase.co https://api.anthropic.com https://api.openai.com https://generativelanguage.googleapis.com; frame-src https://challenges.cloudflare.com; object-src 'none'; base-uri 'self'; form-action 'self'" always;

           # Cache static assets with long-lived headers
           location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot)$ {
               expires 1y;
               add_header Cache-Control "public, immutable";

               # Re-add security headers for static assets
               add_header X-Content-Type-Options "nosniff" always;
               add_header X-Frame-Options "DENY" always;
           }

           # Service worker and manifest - no cache
           location ~* (sw\.js|workbox-.*\.js|manifest\.webmanifest)$ {
               expires off;
               add_header Cache-Control "no-cache, no-store, must-revalidate";
               add_header Service-Worker-Allowed "/" always;

               # Re-add security headers
               add_header X-Content-Type-Options "nosniff" always;
           }

           # SPA fallback - all routes serve index.html
           location / {
               try_files $uri $uri/ /index.html;
               expires off;
               add_header Cache-Control "no-cache, no-store, must-revalidate";
           }

           # Health check endpoint
           location /health {
               access_log off;
               return 200 "OK\n";
               add_header Content-Type text/plain;
           }
       }
