**Important considerations:**
- The Dockerfile uses `npm ci --legacy-peer-deps` as specified in vercel.json:2
- nginx.conf mirrors security headers from vercel.json (lines 13-18)
- SPA routing is handled via `try_files $uri $uri/ /index.html` (matches vercel.json:7 rewrite rule)
- Service worker and manifest files have `no-cache` headers (matches vercel.json:22-26)
- Static assets use 1-year cache with `immutable` flag for optimal performance
- Gzip compression reduces bandwidth for text-based assets
- Health check endpoint at `/health` for container orchestration
- The build output directory is `dist` (from package.json:8 and vercel.json:4)

Create `nginx.conf` in the project root to be copied into the nginx:alpine container during Docker build (referenced in Task 26):

```nginx
# Run nginx as non-privileged user (nginx:alpine default)
user nginx;
worker_processes auto;
error_log /var/log/nginx/error.log warn;
pid /var/run/nginx.pid;

events {
    worker_connections 1024;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    # Logging format
    log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                    '$status $body_bytes_sent "$http_referer" '
                    '"$http_user_agent" "$http_x_forwarded_for"';

    access_log /var/log/nginx/access.log main;

    # Performance optimizations
    sendfile on;
    tcp_nopush on;
    tcp_nodelay on;
    keepalive_timeout 65;
    types_hash_max_size 2048;
    client_max_body_size 10M;  # For image uploads in AI features

    # Gzip compression
    gzip on;
    gzip_vary on;
    gzip_proxied any;
    gzip_comp_level 6;
    gzip_types
        text/plain
        text/css
        text/xml
        text/javascript
        application/json
        application/javascript
        application/xml+rss
        application/xhtml+xml
        application/x-font-ttf
        application/x-font-opentype
        application/vnd.ms-fontobject
        image/svg+xml;
    gzip_disable "msie6";

    # HTTP server (port 80)
    server {
        listen 80;
        listen [::]:80;
        server_name _;

        root /usr/share/nginx/html;
        index index.html;

        # Security headers
        add_header X-Frame-Options "SAMEORIGIN" always;
        add_header X-Content-Type-Options "nosniff" always;
        add_header X-XSS-Protection "1; mode=block" always;
        add_header Referrer-Policy "strict-origin-when-cross-origin" always;
        add_header Permissions-Policy "geolocation=(), microphone=(), camera=()" always;

        # CSP header for PWA (allows inline styles/scripts from Vite build)
        add_header Content-Security-Policy "default-src 'self'; script-src 'self' 'unsafe-inline' 'unsafe-eval'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data: blob: https:; connect-src 'self' https://*.supabase.co https://api.anthropic.com https://generativelanguage.googleapis.com https://api.openai.com; manifest-src 'self'; worker-src 'self' blob:;" always;

        # Serve static assets with immutable cache (Vite generates hashed filenames)
        location /assets/ {
            expires 1y;
            add_header Cache-Control "public, max-age=31536000, immutable";
            access_log off;

            # Re-add security headers (add_header in nested location overrides parent)
            add_header X-Frame-Options "SAMEORIGIN" always;
            add_header X-Content-Type-Options "nosniff" always;
            add_header X-XSS-Protection "1; mode=block" always;
            add_header Referrer-Policy "strict-origin-when-cross-origin" always;
        }

        # PWA icons and manifest with moderate caching
        location ~* \.(png|svg|webp|ico|webmanifest)$ {
            expires 7d;
            add_header Cache-Control "public, max-age=604800";
            access_log off;

            add_header X-Frame-Options "SAMEORIGIN" always;
            add_header X-Content-Type-Options "nosniff" always;
        }

        # Service worker must never be cached (workbox handles its own caching)
        location = /sw.js {
            add_header Cache-Control "no-cache, no-store, must-revalidate";
            add_header Pragma "no-cache";
            expires 0;

            add_header X-Frame-Options "SAMEORIGIN" always;
            add_header X-Content-Type-Options "nosniff" always;
            add_header Service-Worker-Allowed "/";
        }

        # Workbox precache manifest
        location = /workbox-*.js {
            add_header Cache-Control "no-cache, no-store, must-revalidate";
            expires 0;
        }

        # index.html should never be cached (SPA entry point)
        location = /index.html {
            add_header Cache-Control "no-cache, no-store, must-revalidate";
            add_header Pragma "no-cache";
            expires 0;

            # Security headers
            add_header X-Frame-Options "SAMEORIGIN" always;
            add_header X-Content-Type-Options "nosniff" always;
            add_header X-XSS-Protection "1; mode=block" always;
            add_header Referrer-Policy "strict-origin-when-cross-origin" always;
        }

        # Health check endpoint for Docker/K8s
        location /health {
            access_log off;
            return 200 "healthy\n";
            add_header Content-Type text/plain;
        }

        # SPA fallback: all non-file requests go to index.html
        location / {
            try_files $uri $uri/ /index.html;
        }

        # Deny access to hidden files (e.g., .env, .git)
        location ~ /\. {
            deny all;
            access_log off;
            log_not_found off;
        }
